import React from 'react'
import {View,Image,StyleSheet,Text} from 'react-native'

const FooterScreen = ({route}) => {
    return (
<View style={styles.header}>
   <Image
     style={styles.appicon3}
     source={require('/assets/homebutton.png')}
   />
   <Image
     style={styles.appicon2}
     source={require('/assets/questionmark.png')}
   />
   <Image
     style={styles.appicon4}
     source={require('/assets/threedots.png')}
   />
   <Image
     style={styles.appicon5}
     source={require('/assets/nextarrow.png')}
   />
   <Image
     style={styles.appicon1}
     source={require('/assets/backarrow.png')}
   />
 </View>

    );
  };


  const styles = StyleSheet.create({
    container: {
      flex: 1,
      backgroundColor: 'black'
    },
    header: {
      flex: .2,
      backgroundImage: 'linear-gradient(to right, #3437eb, #eb34d9)',
      margin: 0,
      height: 100,
      alignItems: 'center',
      justifyContent: 'center',
      flexDirection: 'row'
    },
    appheadingtext: {
      fontSize: 50,
      color: 'white',
      marginLeft: 20
    },
    appicon1: {
      height: 85,
      width: 85,
      marginRight: 1
    },
    appicon2: {
      height: 85,
      width: 85,
      marginRight: 20
    },
    appicon3: {
      height: 85,
      width: 85,
      marginRight: 30
    },
    appicon4: {
      height: 85,
      width: 85,
      marginRight: 40
    },
    appicon5: {
      height: 85,
      width: 85,
      marginRight: 50
    },
    button: {
      flex: 1,
      verticalAlign: 'middle'
    },
    heading: {
      flex: .2,
      alignItems: 'center',
      justifyContent: 'center'
    },
    headingtext: {
      fontSize: 25,
      color: 'white'
    },
    signcontainer: {
      flex: .5,
      backgroundColor: 'grey',   
      alignItems: 'center',
      flexDirection: 'row',
      margin: 50,
      borderRadius: 20,
      flexDirection: 'column'
    },
    input: {
      height: 60,
      margin: 12,
      borderWidth: 1,
      padding: 10,
      backgroundColor: 'white',
      borderRadius: 10
    },
    loginbutton:{
      width: 100,
      height: 50,
      backgroundColor: 'green',
      borderRadius: 20,
      alignItems: 'center',
      justifyContent: 'center',
      marginLeft: 80
    }
  });
export default FooterScreen
